import kmKhAffUrl from './dics/km_KH.aff?url';
import kmKhDicUrl from './dics/km_KH.dic?url';
import kmKhSuggestAffUrl from './dics/km_KH-suggest.aff?url';
import {
  KHMER_BILINGUAL_PRAYER_EXAMPLE,
  KHMER_CALL_TO_WORSHIP_EXAMPLE,
} from './examples/index.ts';
import kmKhFontsCssUrl from './km_KH_fonts.scss?url';
import kmKhKeyboardCssUrl from './km_KH_keyboard.scss?url';
import { createKhmerSpellcheckProvider } from './spellcheck-khmer-provider.ts';

import { kmKhKeyboardPluginData } from './km_KH_keyboard.ts';

const KHMER_WORD_RE = /[\u1780-\u17D3\u17D7\u17DC\u17DD\u200C\u200D.]+/gu;
const KHMER_WORD_EXACT_RE =
  /^[\u1780-\u17D3\u17D7\u17DC\u17DD\u200C\u200D.]+$/u;
const KHMER_BASE_LETTER_RE = /[\u1780-\u17B3]/u;

/** Khmer's word boundary is a zero-width space, not a visible one. */
const ZERO_WIDTH_SPACE = '\u200B';

/**
 * Runs of visible/soft whitespace BETWEEN Khmer letters, which the editor
 * rewrites to the zero-width word separator above. Typing a real space between
 * Khmer words is the common input mistake this repairs on paste and on Format.
 * The capture group is kept, so the generic rewriter in `shared.ts` can splice
 * `$1` + this language's separator without knowing anything about Khmer.
 */
const KHMER_WORD_SEPARATOR_RE =
  /([\u1780-\u17D3])[\t\f\v \u00AD\u00A0\u1680\u2000-\u200A\u200C\u202F\u205F\u3000]+(?=[\u1780-\u17B3])/gu;

/**
 * Every Khmer base letter, as autocomplete trigger characters.
 *
 * Khmer runs without spaces, so there is no separator keystroke for the
 * word-suggest provider to trigger on \u2014 each letter has to be one. The core
 * provider collects these from whatever languages are registered
 * (`getWordSuggestTriggerCharacters()`), so it needs no Khmer range of its own.
 */
const KHMER_SUGGEST_TRIGGER_CHARACTERS = Array.from(
  { length: 0x17b3 - 0x1780 + 1 },
  (_unused, index) => String.fromCharCode(0x1780 + index),
);

/**
 * The webfont this plugin ships (`km_KH_fonts.scss`) and the system Khmer
 * faces it falls back to. Declared HERE, once: nothing outside this plugin
 * names `editor-Battambang`. Everything that needs the name reads it back:
 * the component plugins' `language.fontFaces` + preview stack
 * (`km_KH_component_plugins.ts`), the PowerPoint export's face detection, the
 * app's initial font wait, and both font pickers (through
 * `getRegisteredPluginFonts()`).
 */
const KM_KH_WEBFONT_FACE = 'editor-Battambang';
const KM_KH_SYSTEM_FONT_FACES = [];
const KM_KH_FONT_FACES = [KM_KH_WEBFONT_FACE, ...KM_KH_SYSTEM_FONT_FACES];
/** Khmer glyphs, so a font-load probe actually resolves the Khmer face. */
const KM_KH_FONT_SAMPLE_TEXT =
  '\u1785\u1798\u17D2\u179A\u17C0\u1784\u179F\u17B6\u1780\u179B\u17D2\u1794\u1784';

function normalizeKhmerWord(word) {
  return String(word || '').replace(/^[\u200C\u200D]+|[\u200C\u200D]+$/gu, '');
}

const olEditorPluginData = {
  id: 'km_KH_ol_editor',
  /**
   * The Khmer example songs ship WITH the plugin (`examples/`), not with the
   * core package: a page that composes km-KH gets them in its Examples menu
   * (via `getRegisteredPluginDraftExamples()`), one that doesn't never bundles
   * them. No `exampleEditorShellModes` restriction — they are offered on
   * whichever shell registered the plugin.
   */
  exampleGroupTitle: 'Khmer .md Examples',
  examples: [
    {
      id: 'khmer-call-to-worship',
      fileName: 'khmer-call-to-worship.md',
      title: 'ព្រះគុណនៅព្រឹកនេះ',
      description:
        'Khmer-only worship draft with a simple intro, verses, and chorus.',
      content: KHMER_CALL_TO_WORSHIP_EXAMPLE,
    },
    {
      id: 'khmer-bilingual-prayer',
      fileName: 'khmer-bilingual-prayer.md',
      title: 'អធិស្ឋានដោយសេចក្ដីសង្ឃឹម',
      description:
        'Khmer and English line pairs for a prayer-focused Open Lyric draft.',
      content: KHMER_BILINGUAL_PRAYER_EXAMPLE,
    },
  ],
  keyboard: kmKhKeyboardPluginData,
  spellChecker: {
    actionLabel: 'Khmer Spell Checker',
    af: kmKhAffUrl,
    aliases: ['km-kh', 'km_kh'],
    baseLetterPattern: KHMER_BASE_LETTER_RE,
    defaultEnabled: true,
    dictionaryName: 'km_KH',
    dict: kmKhDicUrl,
    displayName: 'Khmer',
    exactWordPattern: KHMER_WORD_EXACT_RE,
    languageCode: 'km',
    normalizeWord: normalizeKhmerWord,
    providerFactory: createKhmerSpellcheckProvider,
    suggestAffUrls: [kmKhSuggestAffUrl],
    wordPattern: KHMER_WORD_RE,

    /* ---- script behaviour the core used to hard-code for Khmer ---- */

    /**
     * This script separates words with an invisible character. The core reads
     * it for the word-suggest accept suffix, for deciding that a zero-width
     * space in a line is a real separator rather than stray invisible junk,
     * and (with {@link wordSeparatorPattern}) for repairing typed spaces.
     * Languages that omit it are treated as plain-space separated.
     */
    wordSeparator: ZERO_WIDTH_SPACE,
    wordSeparatorPattern: KHMER_WORD_SEPARATOR_RE,
    /** See {@link KHMER_SUGGEST_TRIGGER_CHARACTERS}. */
    suggestTriggerCharacters: KHMER_SUGGEST_TRIGGER_CHARACTERS,
    /**
     * Menu label for the re-segmentation command. The command itself is
     * offered by the provider (`getSegmentationSuggestion`), which is what
     * gates the entry — this only names it, so the core spells out no
     * language.
     */
    segmentationActionLabel: 'Try Khmer Segmentation',
  },
  // The Khmer faces first (declared before anything renders with the stack),
  // then the NiDA keyboard chrome. The registry injects both into the page
  // `<head>` and the print/export surface includes them via
  // `getRegisteredPluginStyles()`.
  style: [kmKhFontsCssUrl, kmKhKeyboardCssUrl],
  /**
   * The faces this plugin makes available to every host that registers it,
   * read back through `getRegisteredPluginFonts()`. The core no longer names
   * any Khmer face: the app's initial font wait probes whatever is registered
   * here, and the app-page preview font-family datalist lists it.
   */
  fonts: {
    faces: KM_KH_FONT_FACES,
    stack: `${KM_KH_FONT_FACES.map((face) => `'${face}'`).join(', ')}, sans-serif`,
    sampleText: KM_KH_FONT_SAMPLE_TEXT,
  },
  /**
   * BCP-47 locales this plugin adds to the transcript plugin's locale picker,
   * ahead of its alphabetical block. Offering only — the transcript surface
   * starts on `DEFAULT_TRANSCRIPT_LOCALE` (`en-US`) on every page, whatever is
   * registered here, so composing km-KH never silently switches the
   * transcription language on the user. Picking `km-KH` is their call, and the
   * pick persists.
   *
   * It does still set the fallback locale tagged onto mobile keyboard
   * dictation (`getKeyboardTranscriptDefaultLocale()`), which is what routes
   * that text through Khmer word segmentation.
   */
  transcriptLocales: ['km-KH'],
  pptxStyle: {
    fontFamilyChoices: KM_KH_SYSTEM_FONT_FACES,
    fontDetectionSampleText: `WWWWmmmm1234567890${KM_KH_FONT_SAMPLE_TEXT}`,
    fontSize: 24,
  },
};

export { olEditorPluginData };
