import kmKhFontsCssUrl from './km_KH_fonts.scss?url';
import kmKhKeyboardCssUrl from './km_KH_keyboard.scss?url';
import { olEditorPluginData } from './km_KH_ol_editor.ts';
import { EditorPreferencesStore } from '../../editor/scripts/app/EditorPreferencesStore.ts';
import {
  getRegisteredKeyboardSpecifications,
  getRegisteredSpellcheckSpecification,
  registerPlugin,
  unregisterPlugin,
} from '../../editor/scripts/editor-plugin-registry.ts';
import type {
  OpenLyricComponentHost,
  OpenLyricContributions,
  OpenLyricPlugin,
  OpenLyricSurface,
} from '../../editor/components/index.ts';

/**
 * km-KH expressed in the generic per-component plugin contract from
 * `research/editor-structure-implemented.md` — one class per surface, because
 * each surface consumes a different subset:
 *
 * - {@link EditorPluginKmKh}                   — `editor`: fonts + the
 *   Hunspell spellcheck spec + the NiDA on-screen keyboard (mounted live on
 *   a standalone `Editor`, Ctrl+Alt+K via Monaco actions).
 * - {@link OpenLyricMarkdownManagerPluginKmKh} — `markdown`: fonts.
 * - {@link OpenLyricPluginKmKh}                — `lyric`: fonts.
 *
 * All contribution data is the real km_KH plugin data (`km_KH_ol_editor.ts`)
 * — dictionaries, word patterns, provider factory, keyboard spec — not a
 * parallel copy. The spellcheck contribution is declarative today: hosts
 * validate it (reserved `en`, duplicate codes) and the wrapped application
 * still runs the workers; a standalone `Editor` consuming the spec directly
 * is the next migration phase.
 */

/**
 * Khmer-capable faces + the stack that resolves them, both read back from the
 * plugin's own registry data (`km_KH_ol_editor.ts`) — the one place any Khmer
 * face is named. The same data reaches the app pages through the global
 * registry (`getRegisteredPluginFonts()`); this is the component-contract half
 * of it, for surfaces composed without a wrapped application.
 */
const KM_KH_FONT_FACES = olEditorPluginData.fonts.faces;

const KM_KH_FONT_STACK = olEditorPluginData.fonts.stack;

/**
 * The Khmer `@font-face` declarations, shipped BY this plugin
 * (`km_KH_fonts.scss`) — not by the core stylesheet — so any surface that
 * composes km-KH gets the faces, bare embeds included. The sheet also
 * publishes `--ol-plugin-km-kh-font-family`, so a host page can style its own
 * Khmer chrome from the plugin's stack instead of naming the face itself.
 */
const KM_KH_FONT_FACES_STYLE = { href: kmKhFontsCssUrl };

/**
 * Font styling for preview surfaces (stack + the faces it resolves to),
 * declared as data the surface applies — NOT as a stylesheet that restyles
 * every document the moment this plugin is composed.
 *
 * The preview resolves it per document: it applies while the song's
 * `ol:Config` declares a `Locales` entry matching this plugin's key (`km-KH`),
 * and stays off a Latin song rendered on the very same surface. A host's own
 * `fontFamily` still outranks it. The `locales` list is left implicit — the
 * component contract defaults it to the plugin id, which IS the locale here.
 *
 * It reaches the DOM as the `--ol-font-family` *variable* rather than
 * `font-family` itself, because every preview render root already consumes
 * that variable. Declaring the property directly used to lose both ways: an
 * inline `font-family: var(--ol-font-family, inherit)` beats any sheet on a
 * standalone embed, and the app panels' own `.ol-<surface>-panel
 * [data-ol-ref=…]` rules outrank a bare `.ol-preview-root` on specificity.
 */
const KM_KH_PREVIEW_FONT_CONTRIBUTION = {
  fontFaces: KM_KH_FONT_FACES,
  fontFamily: KM_KH_FONT_STACK,
};

const kmKhLanguageContribution = {
  spellcheck: olEditorPluginData.spellChecker,
  keyboard: {
    id: olEditorPluginData.keyboard.id,
    displayName: olEditorPluginData.keyboard.displayName,
    create: olEditorPluginData.keyboard.create,
    // Monaco action ids this keyboard registers, so a standalone chrome can
    // trigger it without naming a language.
    openActionId: olEditorPluginData.keyboard.openActionId,
    closeActionId: olEditorPluginData.keyboard.closeActionId,
  },
  // No `fontFaces` on the editor surface, on purpose: composing km-KH must not
  // restyle the text being edited. `Editor` renders Monaco and the textareas
  // with its own font whatever is attached, and Khmer falls through to the
  // browser's default face for the script. The faces still ship for the
  // PREVIEW surfaces below (and the app pages' font pickers, through the
  // global registry), where the rendered song is what they are for.
};

interface KhmerKeyboardController {
  close(): void;
  destroy(): void;
  toggle(): void;
}

/** Duck-typed view of `Editor` the keyboard needs (see its docs). */
interface MonacoEditorHostLike {
  monacoEditor?: unknown;
  monacoNamespace?: unknown;
}

/** km-KH for the `editor` surface (`gep`). */
class EditorPluginKmKh implements OpenLyricPlugin {
  readonly id = 'km-KH';
  readonly apiVersion = 1 as const;
  readonly surfaces: readonly OpenLyricSurface[] = ['editor'];
  readonly contributes: OpenLyricContributions = {
    language: kmKhLanguageContribution,
    // The Khmer faces plus the NiDA keyboard chrome, active only while the
    // plugin is attached.
    style: [KM_KH_FONT_FACES_STYLE, { href: kmKhKeyboardCssUrl }],
  };

  private keyboardController: KhmerKeyboardController | null = null;
  /** Same store the application uses, so keyboard prefs stay shared. */
  private readonly preferences = new EditorPreferencesStore();

  /** The global-registry registration this instance owns, if any. */
  private registryRegistration: ReturnType<typeof registerPlugin> | null = null;

  /**
   * Publish the registry data through the GLOBAL plugin registry, so a
   * wrapped application (the app pages) boots Khmer spellcheck, the NiDA
   * keyboard, and the PPTX font styles from it. The dashboard no longer
   * registers km-KH as a built-in — composing this plugin is the only thing
   * that enables it. Guarded: with the km spellcheck or the NiDA keyboard
   * already registered (a second editor, an inline page registration) this
   * instance owns nothing.
   *
   * Runs synchronously from `addPlugin()`, i.e. before the dashboard boots.
   */
  install(): void {
    const spellcheckRegistered = Boolean(
      getRegisteredSpellcheckSpecification(
        olEditorPluginData.spellChecker.languageCode,
      ),
    );
    const keyboardRegistered = getRegisteredKeyboardSpecifications().some(
      (specification) => specification.id === olEditorPluginData.keyboard.id,
    );
    if (!spellcheckRegistered && !keyboardRegistered) {
      this.registryRegistration = registerPlugin(olEditorPluginData);
    }
  }

  uninstall(): void {
    this.destroyKeyboard();
    if (this.registryRegistration) {
      unregisterPlugin(this.registryRegistration);
      this.registryRegistration = null;
    }
  }

  onMount(host: OpenLyricComponentHost): void {
    const editorHost = host as unknown as MonacoEditorHostLike;
    const monacoEditor = editorHost.monacoEditor;
    const monaco = editorHost.monacoNamespace;

    // The on-screen keyboard is Monaco-only; the textarea fallback (and any
    // non-Editor host) still gets the font/spellcheck declarations.
    if (!monacoEditor || !monaco) {
      return;
    }

    const ownerDocument = host.container?.ownerDocument ?? document;

    try {
      // Registers its own Ctrl+Alt+K open/close Monaco actions and anchors
      // the keyboard UI to the editor's DOM node inside the host container.
      this.keyboardController = olEditorPluginData.keyboard.create({
        editor: monacoEditor,
        monaco,
        onStateChange: () => {},
        ownerDocument,
        ownerWindow: ownerDocument.defaultView ?? window,
        preferences: this.preferences,
        refs: null,
      });
    } catch (error) {
      console.error('km-KH keyboard failed to mount.', error);
      this.keyboardController = null;
    }
  }

  onUnmount(): void {
    this.destroyKeyboard();
  }

  /** Programmatic access mirroring the Ctrl+Alt+K Monaco actions. */
  toggleKeyboard(): void {
    this.keyboardController?.toggle();
  }

  closeKeyboard(): void {
    this.keyboardController?.close();
  }

  get isKeyboardMounted(): boolean {
    return this.keyboardController !== null;
  }

  private destroyKeyboard(): void {
    try {
      this.keyboardController?.destroy();
    } catch (error) {
      console.error('km-KH keyboard failed to dispose.', error);
    }
    this.keyboardController = null;
  }
}

/** km-KH for the `markdown` surface (`gmp`): Khmer-capable fonts. */
class OpenLyricMarkdownManagerPluginKmKh implements OpenLyricPlugin {
  readonly id = 'km-KH';
  readonly apiVersion = 1 as const;
  readonly surfaces: readonly OpenLyricSurface[] = ['markdown'];
  readonly contributes: OpenLyricContributions = {
    language: KM_KH_PREVIEW_FONT_CONTRIBUTION,
    style: [KM_KH_FONT_FACES_STYLE],
  };

  install(): void {}
  uninstall(): void {}
}

/** km-KH for the `lyric` surface (`glpp`): Khmer-capable fonts. */
class OpenLyricPluginKmKh implements OpenLyricPlugin {
  readonly id = 'km-KH';
  readonly apiVersion = 1 as const;
  readonly surfaces: readonly OpenLyricSurface[] = ['lyric'];
  readonly contributes: OpenLyricContributions = {
    language: KM_KH_PREVIEW_FONT_CONTRIBUTION,
    style: [KM_KH_FONT_FACES_STYLE],
  };

  install(): void {}
  uninstall(): void {}
}

export {
  EditorPluginKmKh,
  OpenLyricMarkdownManagerPluginKmKh,
  OpenLyricPluginKmKh,
};
